00056 inline Position recalcPosition(const ChromaFormat _cf, const ComponentID srcCId, const ComponentID dstCId, const Position &pos)
00057 {
00058   if( toChannelType( srcCId ) == toChannelType( dstCId ) )
00059   {
00060     return pos;
00061   }
00062   else if (isLuma(srcCId) && isChroma(dstCId))
00063   {
00064     return Position(pos.x >> getComponentScaleX(dstCId, _cf), pos.y >> getComponentScaleY(dstCId, _cf));
00065   }
00066   else
00067   {
00068     return Position(pos.x << getComponentScaleX(srcCId, _cf), pos.y << getComponentScaleY(srcCId, _cf));
00069   }
00070 }
00071 
00072 inline Position recalcPosition( const ChromaFormat _cf, const ChannelType srcCHt, const ChannelType dstCHt, const Position &pos )
00073 {
00074   if( srcCHt == dstCHt )
00075   {
00076     return pos;
00077   }
00078   else if( isLuma( srcCHt ) && isChroma( dstCHt ) )
00079   {
00080     return Position( pos.x >> getChannelTypeScaleX( dstCHt, _cf ), pos.y >> getChannelTypeScaleY( dstCHt, _cf ) );
00081   }
00082   else
00083   {
00084     return Position( pos.x << getChannelTypeScaleX( srcCHt, _cf ), pos.y << getChannelTypeScaleY( srcCHt, _cf ) );
00085   }
00086 }
00087 
00088 inline Size recalcSize( const ChromaFormat _cf, const ComponentID srcCId, const ComponentID dstCId, const Size &size )
00089 {
00090   if( toChannelType( srcCId ) == toChannelType( dstCId ) )
00091   {
00092     return size;
00093   }
00094   else if( isLuma( srcCId ) && isChroma( dstCId ) )
00095   {
00096     return Size( size.width >> getComponentScaleX( dstCId, _cf ), size.height >> getComponentScaleY( dstCId, _cf ) );
00097   }
00098   else
00099   {
00100     return Size( size.width << getComponentScaleX( srcCId, _cf ), size.height << getComponentScaleY( srcCId, _cf ) );
00101   }
00102 }
00103 
00104 inline Size recalcSize( const ChromaFormat _cf, const ChannelType srcCHt, const ChannelType dstCHt, const Size &size )
00105 {
00106   if( srcCHt == dstCHt )
00107   {
00108     return size;
00109   }
00110   else if( isLuma( srcCHt ) && isChroma( dstCHt ) )
00111   {
00112     return Size( size.width >> getChannelTypeScaleX( dstCHt, _cf ), size.height >> getChannelTypeScaleY( dstCHt, _cf ) );
00113   }
00114   else
00115   {
00116     return Size( size.width << getChannelTypeScaleX( srcCHt, _cf ), size.height << getChannelTypeScaleY( srcCHt, _cf ) );
00117   }
00118 }
