00124 struct CompArea : public Area
00125 {
00126   CompArea() : Area(), chromaFormat(NUM_CHROMA_FORMAT), compID(MAX_NUM_TBLOCKS)                                                                                                                                 { }
00127   CompArea(const ComponentID _compID, const ChromaFormat _cf, const Area &_area, const bool isLuma = false)                                          : Area(_area),          chromaFormat(_cf), compID(_compID) { if (isLuma) xRecalcLumaToChroma(); }
00128   CompArea(const ComponentID _compID, const ChromaFormat _cf, const Position& _pos, const Size& _size, const bool isLuma = false)                    : Area(_pos, _size),    chromaFormat(_cf), compID(_compID) { if (isLuma) xRecalcLumaToChroma(); }
00129   CompArea(const ComponentID _compID, const ChromaFormat _cf, const uint32_t _x, const uint32_t _y, const uint32_t _w, const uint32_t _h, const bool isLuma = false) : Area(_x, _y, _w, _h), chromaFormat(_cf), compID(_compID) { if (isLuma) xRecalcLumaToChroma(); }
00130 
00131   ChromaFormat chromaFormat;
00132   ComponentID compID;
00133 
00134   Position chromaPos() const;
00135   Position lumaPos()   const;
00136 
00137   Size     chromaSize() const;
00138   Size     lumaSize()   const;
00139 
00140   Position compPos( const ComponentID compID ) const;
00141   Position chanPos( const ChannelType chType ) const;
00142 
00143   Position topLeftComp    (const ComponentID _compID) const { return recalcPosition(chromaFormat, compID, _compID, *this);                                                     }
00144   Position topRightComp   (const ComponentID _compID) const { return recalcPosition(chromaFormat, compID, _compID, { (PosType) (x + width - 1), y                          }); }
00145   Position bottomLeftComp (const ComponentID _compID) const { return recalcPosition(chromaFormat, compID, _compID, { x                        , (PosType) (y + height - 1 )}); }
00146   Position bottomRightComp(const ComponentID _compID) const { return recalcPosition(chromaFormat, compID, _compID, { (PosType) (x + width - 1), (PosType) (y + height - 1 )}); }
00147 
00148   bool valid() const { return chromaFormat < NUM_CHROMA_FORMAT && compID < MAX_NUM_TBLOCKS && width != 0 && height != 0; }
00149 
00150   const bool operator==(const CompArea &other) const
00151   {
00152     if (chromaFormat != other.chromaFormat) return false;
00153     if (compID       != other.compID)       return false;
00154 
00155     return Position::operator==(other) && Size::operator==(other);
00156   }
00157 
00158   const bool operator!=(const CompArea &other) const { return !(operator==(other)); }
00159 
00160 #if REUSE_CU_RESULTS_WITH_MULTIPLE_TUS
00161   void     resizeTo          (const Size& newSize)          { Size::resizeTo(newSize); }
00162 #endif
00163   void     repositionTo      (const Position& newPos)       { Position::repositionTo(newPos); }
00164   void     positionRelativeTo(const CompArea& origCompArea) { Position::relativeTo(origCompArea); }
00165 
00166 private:
00167 
00168   void xRecalcLumaToChroma();
00169 };
