00180 typedef static_vector<CompArea, MAX_NUM_TBLOCKS> UnitBlocksType;
00181 
00182 struct UnitArea
00183 {
00184   ChromaFormat chromaFormat;
00185   UnitBlocksType blocks;
00186 
00187   UnitArea() : chromaFormat(NUM_CHROMA_FORMAT) { }
00188   UnitArea(const ChromaFormat _chromaFormat);
00189   UnitArea(const ChromaFormat _chromaFormat, const Area &area);
00190   UnitArea(const ChromaFormat _chromaFormat, const CompArea  &blkY);
00191   UnitArea(const ChromaFormat _chromaFormat,       CompArea &&blkY);
00192   UnitArea(const ChromaFormat _chromaFormat, const CompArea  &blkY, const CompArea  &blkCb, const CompArea  &blkCr);
00193   UnitArea(const ChromaFormat _chromaFormat,       CompArea &&blkY,       CompArea &&blkCb,       CompArea &&blkCr);
00194 
00195         CompArea& Y()                                  { return blocks[COMPONENT_Y];  }
00196   const CompArea& Y()                            const { return blocks[COMPONENT_Y];  }
00197         CompArea& Cb()                                 { return blocks[COMPONENT_Cb]; }
00198   const CompArea& Cb()                           const { return blocks[COMPONENT_Cb]; }
00199         CompArea& Cr()                                 { return blocks[COMPONENT_Cr]; }
00200   const CompArea& Cr()                           const { return blocks[COMPONENT_Cr]; }
00201 
00202         CompArea& block(const ComponentID comp)       { return blocks[comp]; }
00203   const CompArea& block(const ComponentID comp) const { return blocks[comp]; }
00204 
00205   bool contains(const UnitArea& other) const;
00206   bool contains(const UnitArea& other, const ChannelType chType) const;
00207 
00208         CompArea& operator[]( const int n )       { return blocks[n]; }
00209   const CompArea& operator[]( const int n ) const { return blocks[n]; }
00210 
00211   const bool operator==(const UnitArea &other) const
00212   {
00213     if (chromaFormat != other.chromaFormat)   return false;
00214     if (blocks.size() != other.blocks.size()) return false;
00215 
00216     for (uint32_t i = 0; i < blocks.size(); i++)
00217     {
00218       if (blocks[i] != other.blocks[i]) return false;
00219     }
00220 
00221     return true;
00222   }
00223 
00224 #if REUSE_CU_RESULTS_WITH_MULTIPLE_TUS
00225   void resizeTo    (const UnitArea& unit);
00226 #endif
00227   void repositionTo(const UnitArea& unit);
00228 
00229   const bool operator!=(const UnitArea &other) const { return !(*this == other); }
00230 
00231   const Position& lumaPos () const { return Y(); }
00232   const Size&     lumaSize() const { return Y(); }
00233 
00234   const Position& chromaPos () const { return Cb(); }
00235   const Size&     chromaSize() const { return Cb(); }
00236 
00237   const UnitArea  singleComp(const ComponentID compID) const;
00238   const UnitArea  singleChan(const ChannelType chType) const;
00239 
00240   const SizeType  lwidth()  const { return Y().width; }  
00241   const SizeType  lheight() const { return Y().height; } 
00243   const PosType   lx() const { return Y().x; }           
00244   const PosType   ly() const { return Y().y; }           
00246   bool valid() const { return chromaFormat != NUM_CHROMA_FORMAT && blocks.size() > 0; }
00247 };
00248 
00249 inline UnitArea clipArea(const UnitArea &area, const UnitArea &boundingBox)
00250 {
00251   UnitArea ret(area.chromaFormat);
00252 
00253   for (uint32_t i = 0; i < area.blocks.size(); i++)
00254   {
00255     ret.blocks.push_back(clipArea(area.blocks[i], boundingBox.blocks[i]));
00256   }
00257 
00258   return ret;
00259 }
00260 
00261 struct UnitAreaRelative : public UnitArea
00262 {
00263   UnitAreaRelative(const UnitArea& origUnit, const UnitArea& unit)
00264   {
00265     *((UnitArea*)this) = unit;
00266     for(uint32_t i = 0; i < blocks.size(); i++)
00267     {
00268       blocks[i].positionRelativeTo(origUnit.blocks[i]);
00269     }
00270   }
00271 };
