00302   uint8_t          qtDepth; // number of applied quad-splits, before switching to the multi-type-tree (mtt)
00303   // a triple split would increase the mtDepth by 1, but the qtDepth by 2 in the first and last part and by 1 in the middle part (because of the 1-2-1 split proportions)
00304   uint8_t          btDepth; // number of applied binary splits, after switching to the mtt (or it's equivalent)
00305   uint8_t          mtDepth; // the actual number of splits after switching to mtt (equals btDepth if only binary splits are allowed)
