00313   bool           mmvdSkip;
00314   bool           affine;
00315   int            affineType;
00316   bool           colorTransform;
00317   bool           geoFlag;
00318   int            bdpcmMode;
00319   int            bdpcmModeChroma;
00320   uint8_t          imv;
00321   bool           rootCbf;
00322   uint8_t        sbtInfo;
00323   uint32_t           tileIdx;
00324   uint8_t         mtsFlag;
00325   uint32_t        lfnstIdx;
00326   uint8_t         BcwIdx;
00327   int             refIdxBi[2];
00328   bool           mipFlag;
00329 
00330   // needed for fast imv mode decisions
00331   int8_t          imvNumCand;
00332   uint8_t          smvdMode;
00333   uint8_t        ispMode;
00334   bool           useEscape[MAX_NUM_CHANNEL_TYPE];
00335   bool           useRotation[MAX_NUM_CHANNEL_TYPE];
00336   bool           reuseflag[MAX_NUM_CHANNEL_TYPE][MAXPLTPREDSIZE];
00337   uint8_t        lastPLTSize[MAX_NUM_CHANNEL_TYPE];
00338   uint8_t        reusePLTSize[MAX_NUM_CHANNEL_TYPE];
00339   uint8_t        curPLTSize[MAX_NUM_CHANNEL_TYPE];
00340   Pel            curPLT[MAX_NUM_COMPONENT][MAXPLTSIZE];
