00348   void initData();
00349 
00350   unsigned    idx;
00351   CodingUnit *next;
00352 
00353   PredictionUnit *firstPU;
00354   PredictionUnit *lastPU;
00355 
00356   TransformUnit *firstTU;
00357   TransformUnit *lastTU;
00358 #if ENABLE_SPLIT_PARALLELISM
00359 
00360   int64_t cacheId;
00361   bool    cacheUsed;
00362 #endif
00363   const uint8_t     getSbtIdx() const { assert( ( ( sbtInfo >> 0 ) & 0xf ) < NUMBER_SBT_IDX ); return ( sbtInfo >> 0 ) & 0xf; }
00364   const uint8_t     getSbtPos() const { return ( sbtInfo >> 4 ) & 0x3; }
00365   void              setSbtIdx( uint8_t idx ) { CHECK( idx >= NUMBER_SBT_IDX, "sbt_idx wrong" ); sbtInfo = ( idx << 0 ) + ( sbtInfo & 0xf0 ); }
00366   void              setSbtPos( uint8_t pos ) { CHECK( pos >= 4, "sbt_pos wrong" ); sbtInfo = ( pos << 4 ) + ( sbtInfo & 0xcf ); }
00367   uint8_t           getSbtTuSplit() const;
00368   const uint8_t     checkAllowedSbt() const;
00369   const bool        checkCCLMAllowed() const;
00370   const bool        isSepTree() const;
00371   const bool        isLocalSepTree() const;
00372   const bool        isConsInter() const { return modeType == MODE_TYPE_INTER; }
00373   const bool        isConsIntra() const { return modeType == MODE_TYPE_INTRA; }
00374 };
