00519 template <typename T> class UnitIterator : public std::iterator<std::forward_iterator_tag, T>
00520 {
00521 private:
00522   T* m_punit;
00523 
00524 public:
00525   UnitIterator(           ) : m_punit( nullptr ) { }
00526   UnitIterator( T* _punit ) : m_punit( _punit  ) { }
00527 
00528   typedef T&       reference;
00529   typedef T const& const_reference;
00530   typedef T*       pointer;
00531   typedef T const* const_pointer;
00532 
00533   reference        operator*()                                      { return *m_punit; }
00534   const_reference  operator*()                                const { return *m_punit; }
00535   pointer          operator->()                                     { return  m_punit; }
00536   const_pointer    operator->()                               const { return  m_punit; }
00537 
00538   UnitIterator<T>& operator++()                                     { m_punit = m_punit->next; return *this; }
00539   UnitIterator<T>  operator++( int )                                { auto x = *this; ++( *this ); return x; }
00540   bool             operator!=( const UnitIterator<T>& other ) const { return m_punit != other.m_punit; }
00541   bool             operator==( const UnitIterator<T>& other ) const { return m_punit == other.m_punit; }
00542 };
00543 
00544 template<typename T>
00545 class UnitTraverser
00546 {
00547 private:
00548   T* m_begin;
00549   T* m_end;
00550 
00551 public:
00552   UnitTraverser(                    ) : m_begin( nullptr ), m_end( nullptr ) { }
00553   UnitTraverser( T* _begin, T* _end ) : m_begin( _begin  ), m_end( _end    ) { }
00554 
00555   typedef T                     value_type;
00556   typedef size_t                size_type;
00557   typedef T&                    reference;
00558   typedef T const&              const_reference;
00559   typedef T*                    pointer;
00560   typedef T const*              const_pointer;
00561   typedef UnitIterator<T>       iterator;
00562   typedef UnitIterator<const T> const_iterator;
00563 
00564   iterator        begin()        { return UnitIterator<T>( m_begin ); }
00565   const_iterator  begin()  const { return UnitIterator<T>( m_begin ); }
00566   const_iterator  cbegin() const { return UnitIterator<T>( m_begin ); }
00567   iterator        end()          { return UnitIterator<T>( m_end   ); }
00568   const_iterator  end()    const { return UnitIterator<T>( m_end   ); }
00569   const_iterator  cend()   const { return UnitIterator<T>( m_end   ); }
00570 };
